1	//! Chat input: a multi-line, Piton-highlighted editor on the left and a send
2	//! button on the right, in the body of the Code, chain, and Spec tabs. Enter adds a
3	//! line; Ctrl/Cmd+Enter sends, or queues the prompt while the harness works.
4	//! Tab and Shift+Tab cycle the tabs and Esc takes focus out of the input.
5	
6	use std::rc::Rc;
7	use std::sync::Arc;
8	
9	use gpui_kit::Focusable as _;
10	use gpui_kit::assets::IconName;
11	use gpui_kit::component::button::{Button, ButtonVariants};
12	use gpui_kit::component::input::{
13	    CompletionProvider, Editor, EditorState, Enter, Escape, IndentInline, InputEvent, MoveDown,
14	    MoveUp, OutdentInline, Rope,
15	};
16	use gpui_kit::component::tab::{Tab, TabBar};
17	use gpui_kit::component::{ActiveTheme, Disableable, FocusableExt as _};
18	use gpui_kit::prelude::FluentBuilder as _;
19	use gpui_kit::*;
20	use lsp_types::{CompletionContext, CompletionResponse};
21	
22	use crate::completion_menu::CompletionMenu;
23	use crate::harness_mentions;
24	use crate::main_window::FocusChat;
25	use crate::piton_lsp::PitonSession;
26	use crate::piton_syntax;
27	use crate::project_directory::ProjectDirectory;
28	use crate::project_lsp::ProjectLsp;
29	
30	/// The input grows with its text up to this many rows, then scrolls.
31	const MAX_ROWS: usize = 12;
32	
33	/// Room the editor keeps free at the right of each line when soft wrapping.
34	const WRAP_RIGHT_MARGIN: Pixels = px(10.);
35	
36	#[cfg(target_os = "macos")]
37	const SEND_SHORTCUT: &str = "⌘Enter";
38	#[cfg(not(target_os = "macos"))]
39	const SEND_SHORTCUT: &str = "Ctrl+Enter";
40	
41	/// The tabs the input sits in, in the order Tab cycles them.
42	const TABS: [SendMode; 3] = [SendMode::Code, SendMode::Both, SendMode::Spec];
43	
44	/// The side of the square chain tab, half the height of the tabs.
45	const BOTH_TAB_SIZE: Pixels = px(16.);
46	
47	/// Index of the chain tab in `TABS`.
48	const BOTH_TAB: usize = 1;
49	
50	/// The gap between Code and Spec while the chain is inactive: the chain, with
51	/// room either side so it overlaps neither tab.
52	const CHAIN_GAP: Pixels = px(16. + 6. * 2.);
53	
54	/// How the tabs slide toward and away from the chain: critically damped, so
55	/// they meet without bouncing past the seam.
56	const CHAIN_SPRING: SpringConfig = SpringConfig::new(400., 40., 1.);
57	
58	/// What a prompt is sent to work on: the selected tab.
59	#[derive(Clone, Copy, Debug, PartialEq)]
60	pub enum SendMode {
61	    Code,
62	    /// The code and the spec together.
63	    Both,
64	    Spec,
65	}
66	
67	impl SendMode {
68	    fn label(self) -> &'static str {
69	        match self {
70	            SendMode::Code => "Code",
71	            SendMode::Both => "Code and Spec",
72	            SendMode::Spec => "Spec",
73	        }
74	    }
75	
76	    fn id(self) -> &'static str {
77	        match self {
78	            SendMode::Code => "code-tab",
79	            SendMode::Both => "both-tab",
80	            SendMode::Spec => "spec-tab",
81	        }
82	    }
83	}
84	
85	/// Emitted with the input's text, and the mode it is sent in, when the user
86	/// sends it.
87	pub struct Submit {
88	    pub text: String,
89	    pub mode: SendMode,
90	}
91	
92	pub struct ChatInput {
93	    editor: Entity<EditorState>,
94	    completion: Entity<CompletionMenu>,
95	    /// The tab bar and its body, which Esc moves focus to: out of the input,
96	    /// but not onto nothing, where the window would hand it straight back.
97	    focus_handle: FocusHandle,
98	    /// Index into `TABS`.
99	    selected_tab: usize,
100	    lsp: Option<Arc<PitonSession>>,
101	    busy: bool,
102	    /// Width the editor's text was last laid out in, which decides where long
103	    /// lines soft wrap.
104	    text_width: Option<Pixels>,
105	    /// What the editor adds around its rows (padding and border) as last
106	    /// laid out, rounded to device pixels.
107	    chrome: Option<Pixels>,
108	    _subscriptions: Vec<Subscription>,
109	}
110	
111	impl EventEmitter<Submit> for ChatInput {}
112	
113	impl ChatInput {
114	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
115	        let editor = cx.new(|cx| {
116	            EditorState::new(window, cx)
117	                .language(piton_syntax::LANGUAGE_NAME)
118	                .line_number(false)
119	                .folding(false)
120	                .soft_wrap(true)
121	                // No empty rows below the last line: the input is sized to its
122	                // text, so any extra would be blank space, and it would leave
123	                // room for the editor to stay scrolled past the first line
124	                // after Enter grows the input.
125	                .scroll_beyond_last_line(Some(0))
126	                .placeholder(format!(
127	                    "Write a prompt… (/ for skills and commands, @ for agents, {SEND_SHORTCUT} to send)"
128	                ))
129	        });
130	        // Typing goes straight into the input, without clicking it first.
131	        editor.read(cx).focus_handle(cx).focus(window, cx);
132	        let completion = cx.new(|cx| CompletionMenu::new(editor.clone(), window, cx));
133	
134	        let subscriptions = vec![
135	            cx.subscribe_in(&editor, window, |this, editor, event: &InputEvent, window, cx| {
136	                if matches!(event, InputEvent::Change) {
137	                    // An edit may be an accepted completion, whose import the
138	                    // hidden anchor then takes on.
139	                    if let Some(lsp) = &this.lsp {
140	                        lsp.note_edit(&editor.read(cx).value());
141	                    }
142	                    this.completion
143	                        .update(cx, |menu, cx| menu.on_edit(window, cx));
144	                }
145	                // Re-render on every edit so the input can grow to fit its text.
146	                cx.notify();
147	            }),
148	            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.connect_lsp(cx)),
149	        ];
150	
151	        let mut this = Self {
152	            editor,
153	            completion,
154	            focus_handle: cx.focus_handle(),
155	            selected_tab: 0,
156	            lsp: None,
157	            busy: false,
158	            text_width: None,
159	            chrome: None,
160	            _subscriptions: subscriptions,
161	        };
162	        this.connect_lsp(cx);
163	        this
164	    }
