177	    /// follows other text, then moves focus into the input.
178	    pub fn insert_mention(&mut self, mention: &str, window: &mut Window, cx: &mut Context<Self>) {
179	        self.editor.update(cx, |editor, cx| {
180	            let value = editor.value();
181	            let follows_text = value
182	                .get(..editor.cursor())
183	                .and_then(|before| before.chars().next_back())
184	                .is_some_and(|c| !c.is_whitespace());
185	            let text = if follows_text {
186	                format!(" {mention}")
187	            } else {
188	                mention.to_string()
189	            };
190	            editor.insert(text, window, cx);
191	        });
