249	    /// Moves `step` tabs along, wrapping around. An open completion menu
250	    /// keeps its own Tab and Shift+Tab.
251	    fn cycle_tab(&mut self, step: isize, cx: &mut Context<Self>) {
252	        if self.completion.read(cx).is_open() {
253	            return;
254	        }
255	        cx.stop_propagation();
256	        let count = TABS.len() as isize;
257	        self.selected_tab = (self.selected_tab as isize + step).rem_euclid(count) as usize;
258	        cx.notify();
259	    }
