261	    /// Esc closes an open completion menu, and otherwise takes focus out of
262	    /// the input.
263	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
264	        if self.completion.read(cx).is_open() {
265	            self.completion.update(cx, |menu, cx| menu.hide(cx));
266	        } else {
267	            self.focus_handle.focus(window, cx);
268	        }
269	    }
