271	    /// The rows `text` takes in the editor: one per line, plus one for every
272	    /// soft wrap, wrapped the way the editor wraps it.
273	    fn visual_rows(&self, text: &str, window: &Window, cx: &App) -> usize {
274	        let Some(wrap_width) = self.text_width.map(|width| width - WRAP_RIGHT_MARGIN) else {
275	            return text.split('\n').count();
276	        };
277	        let theme = cx.theme();
278	        let mut wrapper = window
279	            .text_system()
280	            .line_wrapper(font(theme.mono_font_family.clone()), theme.mono_font_size);
281	        text.split('\n')
282	            .map(|line| {
283	                1 + wrapper
284	                    .wrap_line(&[LineFragment::text(line)], wrap_width)
285	                    .count()
286	            })
287	            .sum()
288	    }
289	}
