291	impl Render for ChatInput {
292	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
293	        let text = self.editor.read(cx).value();
294	        let rows = self.visual_rows(&text, window, cx).clamp(1, MAX_ROWS);
295	        // Fit the text with the editor's own metrics: its laid-out line height
296	        // plus the padding and border around its rows. Until the editor has
297	        // painted, the border is estimated at a device pixel or more per side.
298	        let line_height = self
299	            .editor
300	            .read(cx)
301	            .line_height()
302	            .unwrap_or_else(|| window.line_height());
303	        let chrome = self.chrome.unwrap_or_else(|| {
304	            gpui_kit::component::Size::Medium.input_py() * 2.
305	                + ceil_to_device_pixel(px(1.), window) * 2.
306	        });
307	        let height = ceil_to_device_pixel(line_height * rows as f32 + chrome, window);
308	        let one_row = ceil_to_device_pixel(line_height + chrome, window);
309	        let empty = text.is_empty();
310	
311	        // Once the editor has painted, check how it was laid out: the width
312	        // its text wrapped in (a resized window wraps long lines differently)
313	        // and the padding and border around its rows. When either changed,
314	        // the input re-fits.
315	        let this = cx.entity().downgrade();
316	        let editor = self.editor.clone();
317	        let track_layout = canvas(
318	            |_, _, _| {},
319	            move |bounds, _, _, cx| {
320	                let Some(text_bounds) = editor.read(cx).text_bounds() else {
321	                    return;
322	                };
323	                let width = text_bounds.size.width;
324	                let chrome = bounds.size.height - text_bounds.size.height;
325	                this.update(cx, |this, cx| {
326	                    let chrome_changed = this
327	                        .chrome
328	                        .is_none_or(|old| (old - chrome).abs() > px(0.01));
329	                    if this.text_width != Some(width) || chrome_changed {
330	                        this.text_width = Some(width);
331	                        if chrome_changed {
332	                            this.chrome = Some(chrome);
333	                        }
334	                        cx.notify();
335	                    }
336	                })
337	                .ok();
338	            },
339	        )
340	        .absolute()
341	        .size_full();
342	
343	        // Code and Spec are full tabs, each its own bar, with a gap between
344	        // them where the chain sits: broken and dimmed until selected, then
345	        // joined. Selecting it selects both tabs, which slide toward the chain
346	        // until they meet beneath it, so they read as one locked tab. The chain
347	        // itself never moves; only the tabs slide.
348	        let selected = self.selected_tab;
349	        let unified = selected == BOTH_TAB;
350	        // How far each tab has slid toward the chain: none while apart, half
351	        // the gap once they meet.
352	        let slide = SpringAnimation::new(CHAIN_SPRING).to(if unified {
353	            CHAIN_GAP * 0.5
354	        } else {
355	            px(0.)
356	        });
357	        let chat_input = cx.entity().downgrade();
358	        let full_tab = |ix: usize| {
359	            let chat_input = chat_input.clone();
360	            let bar = TabBar::new(TABS[ix].id())
361	                .on_click(move |_, window, cx| {
362	                    chat_input
363	                        .update(cx, |this, cx| this.select_tab(ix, window, cx))
364	                        .ok();
365	                })
366	                .child(Tab::new().label(TABS[ix].label()).px_2());
367	            if selected == ix || unified {
368	                bar.selected_index(0)
369	            } else {
370	                bar
371	            }
372	        };
373	        let code = div()
374	            .relative()
375	            .child(full_tab(0))
376	            .with_spring("code-slide", slide.clone(), |this, slide| this.left(slide));
377	        // Spec stretches to the right edge, so it slides by pulling its left
378	        // edge in rather than moving as a whole.
379	        let spec = div()
380	            .flex_1()
381	            .ml(CHAIN_GAP)
382	            .child(full_tab(2).w_full())
383	            .with_spring("spec-slide", slide.clone(), |this, slide| {
384	                this.ml(CHAIN_GAP - slide)
385	            });
386	        let both = Button::new("both")
387	            .outline()
388	            .icon(if unified {
389	                IconName::Link
390	            } else {
391	                IconName::Unlink
392	            })
393	            .tooltip(SendMode::Both.label())
394	            .size(BOTH_TAB_SIZE)
395	            .focus_ring(false)
396	            .tab_stop(false)
397	            .on_click(cx.listener(|this, _, window, cx| this.select_tab(BOTH_TAB, window, cx)));
398	        let both = if unified { both.primary() } else { both };
399	        // The selected tabs' facing borders, covered once the tabs meet.
400	        let meet = CHAIN_GAP * 0.5 - px(0.5);
401	        let seam_cover = cx.theme().tab_active;
402	        let cover = div()
403	            .absolute()
404	            .top_0()
405	            .bottom_0()
406	            .left(px(-1.))
407	            .w(px(2.))
408	            .with_spring("seam-cover", slide, move |this, slide| {
409	                if slide >= meet {
410	                    this.bg(seam_cover)
411	                } else {
412	                    this
413	                }
414	            });
415	        // An invisible copy of the Code tab bar and half the gap put the
416	        // chain's place, whatever width Code's label takes.
417	        let seam = div()
418	            .absolute()
419	            .left_0()
420	            .top_0()
421	            .bottom_0()
422	            .flex()
423	            .child(
424	                TabBar::new("code-tab-width")
425	                    .child(Tab::new().label(SendMode::Code.label()).px_2())
426	                    .invisible(),
427	            )
428	            .child(div().w(CHAIN_GAP * 0.5))
429	            .child(
430	                div()
431	                    .relative()
432	                    .w_0()
433	                    .flex()
434	                    .items_center()
435	                    .child(cover)
436	                    .child(
437	                        div().relative().w_0().h(BOTH_TAB_SIZE).child(
438	                            gpui_kit::TestSupportExt::test_support(
439	                                div()
440	                                    .id(SendMode::Both.id())
441	                                    .absolute()
442	                                    .top_0()
443	                                    .left(BOTH_TAB_SIZE * -0.5)
444	                                    .rounded(cx.theme().radius)
445	                                    .when(unified, |this| this.bg(cx.theme().background))
446	                                    .opacity(if unified { 1. } else { 0.5 })
447	                                    .child(both),
448	                            ),
449	                        ),
450	                    ),
451	            );
452	        let tabs = gpui_kit::TestSupportExt::test_support(
453	            div()
454	                .id("chat-tabs")
455	                .relative()
456	                .flex()
457	                .items_center()
458	                .bg(cx.theme().tab_bar)
459	                .child(
460	                    div()
461	                        .absolute()
462	                        .left_0()
463	                        .bottom_0()
464	                        .size_full()
465	                        .border_b_1()
466	                        .border_color(cx.theme().border),
467	                )
468	                .child(code)
469	                .child(spec)
470	                .child(seam),
471	        );
472	
473	        let body = div().flex().flex_row().items_end().gap_2().p_3();
474	
475	        div()
476	            .track_focus(&self.focus_handle)
477	            .flex()
478	            .flex_col()
479	            .border_t_1()
480	            .border_color(cx.theme().border)
481	            // Tab and Shift+Tab cycle the tabs rather than indenting, and the
482	            // input keeps focus.
483	            .capture_action(cx.listener(|this, _: &IndentInline, _, cx| this.cycle_tab(1, cx)))
484	            .capture_action(cx.listener(|this, _: &OutdentInline, _, cx| this.cycle_tab(-1, cx)))
485	            // Esc arrives as the window's FocusChat, which matches ahead of the
486	            // editor's own binding, or as the editor's Escape once it has
487	            // nothing to cancel. Handled here, neither reaches the window,
488	            // which would focus the input again.
489	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| this.escape(window, cx)))
490	            .on_action(cx.listener(|this, _: &Escape, window, cx| this.escape(window, cx)))
491	            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
492	                // Catch Ctrl/Cmd+Enter before the editor turns it into a newline.
493	                if action.secondary {
494	                    cx.stop_propagation();
495	                    this.submit(window, cx);
496	                } else if this.completion.read(cx).is_open() {
497	                    // Enter accepts the completion instead of adding a line.
498	                    cx.stop_propagation();
499	                    this.completion
500	                        .update(cx, |menu, cx| menu.accept_selected(window, cx));
501	                }
502	            }))
503	            // Up and Down move through an open completion menu instead of
504	            // the text.
505	            .capture_action(cx.listener(|this, _: &MoveUp, window, cx| {
506	                if this.completion.read(cx).is_open() {
507	                    cx.stop_propagation();
508	                    this.completion
509	                        .update(cx, |menu, cx| menu.select_next(-1, window, cx));
510	                }
511	            }))
512	            .capture_action(cx.listener(|this, _: &MoveDown, window, cx| {
513	                if this.completion.read(cx).is_open() {
514	                    cx.stop_propagation();
515	                    this.completion
516	                        .update(cx, |menu, cx| menu.select_next(1, window, cx));
517	                }
518	            }))
519	            .child(tabs)
520	            .child(
521	                body.child(gpui_kit::TestSupportExt::test_support(
522	                    div()
523	                        .id("prompt-editor")
524	                        .relative()
525	                        .flex_1()
526	                        .min_w_0()
527	                        .child(Editor::new(&self.editor).h(height))
528	                        .child(track_layout)
529	                        .child(self.completion.clone()),
530	                ))
531	                .child(
532	                    Button::new("send")
533	                        .primary()
534	                        // While the harness works, sending queues the prompt.
535	                        .label(if self.busy { "Queue" } else { "Send" })
536	                        // As tall as the input's single line, so the two line up.
537	                        .h(one_row)
538	                        .tooltip(if self.busy {
539	                            format!("Queue until the harness is free ({SEND_SHORTCUT})")
540	                        } else {
541	                            format!("Send ({SEND_SHORTCUT})")
542	                        })
543	                        .disabled(empty)
544	                        .on_click(cx.listener(|this, _, window, cx| this.submit(window, cx))),
545	                ),
546	            )
547	    }
548	}
