550	/// Completions for the chat input: harness mentions after `/` or `@`, and
551	/// Piton from `piton lsp`, when it is running, everywhere else.
552	struct PromptCompletions {
553	    lsp: Option<Arc<PitonSession>>,
554	}
555	
556	impl CompletionProvider for PromptCompletions {
557	    fn completions(
558	        &self,
559	        text: &Rope,
560	        offset: usize,
561	        _: CompletionContext,
562	        _: &mut Window,
563	        cx: &mut App,
564	    ) -> Task<Result<CompletionResponse>> {
565	        let lsp = self.lsp.clone();
566	        let prompt = text.to_string();
567	        let project_dir = ProjectDirectory::get(cx);
568	        cx.background_spawn(async move {
569	            if harness_mentions::mention_at(&prompt, offset).is_some() {
570	                let invocables = harness_mentions::discover(project_dir.as_deref());
571	                let items = harness_mentions::complete(&prompt, offset, &invocables);
572	                return Ok(CompletionResponse::Array(items.unwrap_or_default()));
573	            }
574	            // A slash or hyphen only triggers completion inside a mention.
575	            let typed = prompt
576	                .get(..offset)
577	                .and_then(|before| before.chars().next_back());
578	            match lsp {
579	                Some(lsp) if !matches!(typed, Some('/' | '-')) => lsp.complete(&prompt, offset),
580	                _ => Ok(CompletionResponse::Array(Vec::new())),
581	            }
582	        })
583	    }
584	
585	    fn is_completion_trigger(&self, _: usize, new_text: &str, _: &mut App) -> bool {
586	        new_text.chars().last().is_some_and(|c| {
587	            c.is_alphanumeric() || matches!(c, '{' | '.' | '$' | '@' | ':' | '_' | '/' | '-')
588	        })
589	    }
590	}
