848	    /// The Code tab, the chain, and the Spec tab, as last laid out.
849	    fn chain_layout(window: &mut Window, cx: &mut gpui_kit::App) -> (Bounds, Bounds, Bounds) {
850	        window.render_frame(cx);
851	        (
852	            window.within("code-tab").find(0usize).bounds(),
853	            window.find("both-tab").bounds(),
854	            window.within("spec-tab").find(0usize).bounds(),
855	        )
856	    }
