858	    /// Draws frames until the gap between Code and Spec is `gap`.
859	    fn settle_chain(
860	        handle: gpui_kit::AnyWindowHandle,
861	        gap: gpui_kit::Pixels,
862	        cx: &mut TestAppContext,
863	    ) -> (Bounds, Bounds, Bounds) {
864	        let start = std::time::Instant::now();
865	        loop {
866	            let layout = cx
867	                .update_window(handle, |_, window, cx| chain_layout(window, cx))
868	                .unwrap();
869	            let (code, _, spec) = layout;
870	            if (spec.left() - code.right() - gap).abs() <= super::px(0.5) {
871	                return layout;
872	            }
873	            assert!(
874	                start.elapsed() < TIMEOUT,
875	                "the tabs did not settle {gap:?} apart: Code {code:?}, Spec {spec:?}"
876	            );
877	            std::thread::sleep(Duration::from_millis(16));
878	        }
879	    }
