881	    /// The chain is a square half the height of the tabs, centred on them.
882	    /// Inactive, it sits in the gap between Code and Spec, overlapping neither.
883	    /// Active, the tabs slide in until they meet beneath it, and it overlaps
884	    /// both, centred on the seam. The chain stays put throughout.
885	    #[gpui_kit::test]
886	    async fn chain_joins_the_tabs_beneath_it(cx: &mut TestAppContext) {
887	        cx.update(|cx| {
888	            gpui_kit::init(cx);
889	            piton_syntax::init();
890	            ProjectDirectory::init(cx);
891	        });
892	        let window = cx.add_window(|window, cx| {
893	            let input = cx.new(|cx| ChatInput::new(window, cx));
894	            Root::new(input, window, cx)
895	        });
896	        let handle = window.into();
897	        cx.wait_for(handle, TIMEOUT, |window, _| {
898	            window.try_find("prompt-editor").is_some()
899	        })
900	        .await;
901	
902	        let (code, chain, spec) = settle_chain(handle, super::CHAIN_GAP, cx);
903	        assert_eq!(
904	            chain.size.width, chain.size.height,
905	            "chain {chain:?} is not square"
906	        );
907	        assert!(
908	            (chain.size.height - code.size.height * 0.5).abs() <= super::px(0.5),
909	            "chain {chain:?} is not half the height of Code {code:?}"
910	        );
911	        assert!(
912	            (chain.center().y - code.center().y).abs() <= super::px(0.5),
913	            "chain {chain:?} is not centred on Code {code:?}"
914	        );
915	        assert!(
916	            code.right() <= chain.left() && chain.right() <= spec.left(),
917	            "inactive chain {chain:?} overlaps Code {code:?} or Spec {spec:?}"
918	        );
919	        assert!(
920	            (chain.center().x - (code.right() + spec.left()) * 0.5).abs() <= super::px(0.5),
921	            "inactive chain {chain:?} is not centred in the gap"
922	        );
923	        let resting = chain;
924	
925	        // Tab moves to the chain; the tabs slide rather than jump together.
926	        cx.update_window(handle, |_, window, cx| window.press("tab", cx))
927	            .unwrap();
928	        let (code, _, spec) = cx
929	            .update_window(handle, |_, window, cx| chain_layout(window, cx))
930	            .unwrap();
931	        assert!(
932	            spec.left() - code.right() > super::px(1.),
933	            "the tabs met without sliding: Code {code:?}, Spec {spec:?}"
934	        );
935	
936	        let (code, chain, spec) = settle_chain(handle, super::px(0.), cx);
937	        assert_eq!(chain, resting, "the chain moved when activated");
938	        assert!(
939	            chain.left() < code.right() && spec.left() < chain.right(),
940	            "active chain {chain:?} does not overlap Code {code:?} and Spec {spec:?}"
941	        );
942	        assert!(
943	            (chain.center().x - code.right()).abs() <= super::px(0.5),
944	            "active chain {chain:?} is not centred on the seam at {:?}",
945	            code.right()
946	        );
947	
948	        // Back to Code: the tabs slide apart again, around the same chain.
949	        cx.update_window(handle, |_, window, cx| window.press("shift-tab", cx))
950	            .unwrap();
951	        let (_, chain, _) = settle_chain(handle, super::CHAIN_GAP, cx);
952	        assert_eq!(chain, resting, "the chain moved when deactivated");
953	    }
