991	    /// The chat input at the bottom of the window, with a probe laid out
992	    /// after it that notes the editor's scroll offset between prepaint and
993	    /// paint: the offset its text is actually painted at, before paint
994	    /// clamps it for the next frame.
995	    struct Probed {
996	        input: Entity<ChatInput>,
997	        painted_scroll_y: Rc<Cell<gpui_kit::Pixels>>,
998	    }
999	
1000	    impl Render for Probed {
1001	        fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
1002	            let editor = self.input.read(cx).editor.clone();
1003	            let painted_scroll_y = self.painted_scroll_y.clone();
1004	            div()
1005	                .size_full()
1006	                .flex()
1007	                .flex_col()
1008	                .justify_end()
1009	                .child(self.input.clone())
1010	                .child(
1011	                    gpui_kit::canvas(
1012	                        move |_, _, cx| painted_scroll_y.set(editor.read(cx).scroll_offset().y),
1013	                        |_, _, _, _| {},
1014	                    )
1015	                    .absolute()
1016	                    .size_0(),
1017	                )
1018	        }
1019	    }
1020	
1021	    /// What one painted frame of the input looked like.
1022	    #[derive(Debug, Clone, Copy)]
1023	    struct Frame {
1024	        rows: usize,
1025	        top: gpui_kit::Pixels,
1026	        bottom: gpui_kit::Pixels,
1027	        height: gpui_kit::Pixels,
1028	        /// The offset the text was painted at in this frame.
1029	        painted_scroll_y: gpui_kit::Pixels,
1030	        /// The offset the editor kept after painting.
1031	        scroll_y: gpui_kit::Pixels,
1032	        cursor_top: gpui_kit::Pixels,
1033	        cursor_bottom: gpui_kit::Pixels,
1034	    }
1035	
1036	    /// Presses Enter in the input at the bottom of the window, `presses`
1037	    /// times, and records every frame drawn after each press, the way the
1038	    /// window draws them: only what the press invalidated, with no forced
1039	    /// refresh in between.
1040	    async fn frames_after_enter(
1041	        presses: usize,
1042	        scale_factor: f32,
1043	        cx: &mut TestAppContext,
1044	    ) -> (gpui_kit::Pixels, Vec<Vec<Frame>>) {
1045	        cx.update(|cx| {
1046	            gpui_kit::init(cx);
1047	            piton_syntax::init();
1048	            ProjectDirectory::init(cx);
1049	        });
1050	        let mut chat_input = None;
1051	        let painted = Rc::new(Cell::new(gpui_kit::px(0.)));
1052	        let window = cx.add_window(|window, cx| {
1053	            let input = cx.new(|cx| ChatInput::new(window, cx));
1054	            chat_input = Some(input.clone());
1055	            let painted_scroll_y = painted.clone();
1056	            let view = cx.new(|_| Probed {
1057	                input,
1058	                painted_scroll_y,
1059	            });
1060	            Root::new(view, window, cx)
1061	        });
1062	        let chat_input = chat_input.unwrap();
1063	        let editor = chat_input.read_with(cx, |input, _| input.editor.clone());
1064	        let handle = window.into();
1065	        // Most displays are not 2x: at other scales the rows are a fraction
1066	        // of a pixel off the device grid.
1067	        cx.simulate_window_scale_factor_change(handle, scale_factor);
1068	        cx.wait_for(handle, TIMEOUT, |_, cx| {
1069	            editor.read(cx).line_height().is_some()
1070	        })
1071	        .await;
1072	
1073	        let record = |window: &mut Window, cx: &mut gpui_kit::App| {
1074	            window.draw(cx).clear(cx);
1075	            let bounds = window.find("prompt-editor").bounds();
1076	            let editor = editor.read(cx);
1077	            let scroll_y = editor.scroll_offset().y;
1078	            // The cursor is laid out in window coordinates, before scrolling.
1079	            let (cursor, _) = editor.cursor_layout().unwrap();
1080	            let painted_scroll_y = painted.get();
1081	            Frame {
1082	                rows: editor.value().split('\n').count(),
1083	                top: bounds.top(),
1084	                bottom: bounds.bottom(),
1085	                height: bounds.size.height,
1086	                painted_scroll_y,
1087	                scroll_y,
1088	                cursor_top: cursor.top() + painted_scroll_y,
1089	                cursor_bottom: cursor.bottom() + painted_scroll_y,
1090	            }
1091	        };
1092	
1093	        cx.update_window(handle, |_, window, cx| {
1094	            editor.read(cx).focus_handle(cx).focus(window, cx);
1095	            window.render_frame(cx);
1096	            window.render_frame(cx);
1097	            window.input("x", cx);
1098	        })
1099	        .unwrap();
1100	        let line_height = editor.read_with(cx, |editor, _| editor.line_height().unwrap());
1101	
1102	        let mut presses_frames = vec![];
1103	        for _ in 0..presses {
1104	            let frames = cx
1105	                .update_window(handle, |_, window, cx| {
1106	                    let before = record(window, cx);
1107	                    window.dispatch_keystroke(gpui_kit::Keystroke::parse("enter").unwrap(), cx);
1108	                    let mut frames = vec![before];
1109	                    for _ in 0..6 {
1110	                        frames.push(record(window, cx));
1111	                    }
1112	                    frames
1113	                })
1114	                .unwrap();
1115	            cx.run_until_parked();
1116	            presses_frames.push(frames);
1117	        }
1118	        (line_height, presses_frames)
1119	    }
