1121	    /// Enter grows the input by one row in the very next frame, and it stays
1122	    /// put from then on: the bottom edge never moves, the first line never
1123	    /// scrolls out of view, and the cursor is always inside the input.
1124	    async fn assert_enter_grows_without_flicker(scale_factor: f32, cx: &mut TestAppContext) {
1125	        let (line_height, presses) = frames_after_enter(MAX_ROWS + 3, scale_factor, cx).await;
1126	        let bottom = presses[0][0].bottom;
1127	        let one_row = presses[0][0].height;
1128	        for (press, frames) in presses.iter().enumerate() {
1129	            let rows = frames.last().unwrap().rows;
1130	            let expected = one_row + line_height * (rows.min(MAX_ROWS) - 1) as f32;
1131	            for (ix, frame) in frames.iter().enumerate().skip(1) {
1132	                let context = format!(
1133	                    "at {scale_factor}x, line height {line_height:?}, press {press}, frame {ix} of {frames:#?}"
1134	                );
1135	                assert!(
1136	                    (frame.height - expected).abs() <= gpui_kit::px(0.5),
1137	                    "height is not {expected:?} rows: {context}"
1138	                );
1139	                assert!(
1140	                    (frame.bottom - bottom).abs() <= gpui_kit::px(0.5),
1141	                    "the bottom edge moved from {bottom:?}: {context}"
1142	                );
1143	                if rows <= MAX_ROWS {
1144	                    assert!(
1145	                        frame.painted_scroll_y.abs() <= gpui_kit::px(0.5),
1146	                        "painted scrolled although everything fits: {context}"
1147	                    );
1148	                } else {
1149	                    assert!(
1150	                        (frame.painted_scroll_y - frames.last().unwrap().painted_scroll_y).abs()
1151	                            <= gpui_kit::px(0.5),
1152	                        "scroll did not settle in the first frame: {context}"
1153	                    );
1154	                }
1155	                assert!(
1156	                    frame.cursor_top >= frame.top - gpui_kit::px(0.5)
1157	                        && frame.cursor_bottom <= frame.bottom + gpui_kit::px(0.5),
1158	                    "the cursor is outside the input: {context}"
1159	                );
1160	            }
1161	        }
1162	    }
