    let t = (position / 2.).clamp(0., 1.);
    // The shorter way round the hue circle, which from red to blue passes
    // through purple rather than green.
    let hue_step = (blue.h - red.h + 0.5).rem_euclid(1.) - 0.5;
    Hsla {
        h: (red.h + hue_step * t).rem_euclid(1.),
        s: red.s + (blue.s - red.s) * t,
        l: red.l + (blue.l - red.l) * t,
        a: TINT_OPACITY,
    }
}

